#pragma once
static const char METECH_WEB_UI[] = R"HTML(<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Metech Camera</title><style>:root{--bg:#07111d;--card:#0d1c2d;--line:#203752;--text:#eaf2fb;--muted:#93a8bf;--blue:#39a7ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}.wrap{max-width:1180px;margin:auto;padding:20px}.top,.head,.actions,.profiles,.row{display:flex;align-items:center;gap:9px}.top,.head{justify-content:space-between}.top{margin-bottom:18px}.title{font-size:20px;font-weight:750}.sub,.muted,.note{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:1.4fr .9fr;gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:15px}.camera{padding:0;overflow:hidden}.head,.actions{padding:13px 15px}.live{aspect-ratio:1.25;background:#02070d}.live img{width:100%;height:100%;object-fit:contain}.actions{border-top:1px solid var(--line)}button{border:0;border-radius:10px;padding:9px 12px;background:#21364c;color:var(--text);font:inherit;font-weight:650;cursor:pointer}.primary{background:#258fe0}.wide{flex:1}button:disabled{opacity:.5}.stats{display:grid;grid-template-columns:1fr 1fr;gap:9px}.stat{padding:10px;background:#091727;border:1px solid #1a3049;border-radius:11px}.stat b{display:block;margin-top:3px}details{margin-top:16px}summary{cursor:pointer;font-weight:650}.profiles{margin:12px 0}.row{margin:10px 0}.row label{width:105px}.row output{width:30px;text-align:right;color:var(--muted)}input[type=range]{flex:1}input,select{background:#091727;border:1px solid var(--line);border-radius:8px;color:var(--text);padding:8px}.toggles{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.toggles label{font-size:13px}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:9px}.thumb{padding:0;text-align:left;overflow:hidden;border:1px solid var(--line)}.thumb img{width:100%;aspect-ratio:1;object-fit:cover;display:block}.thumb span{display:block;padding:6px;font-size:11px}.empty{color:var(--muted);padding:20px}dialog{background:#08121f;border:1px solid var(--line);border-radius:16px;padding:10px}dialog img{max-width:90vw;max-height:82vh}@media(max-width:760px){.wrap{padding:12px}.grid{grid-template-columns:1fr}.toggles{grid-template-columns:1fr}}</style><main class="wrap"><header class="top"><div><div class="title">Metech Camera</div><div class="sub">OV5640 · Timelapse station</div></div><b id="online">Đang kết nối</b></header><div class="grid"><section class="card camera"><div class="head"><b>Góc nhìn trực tiếp</b><span class="muted">SXGA</span></div><div class="live"><img id="cam" alt="Camera preview"></div><div class="actions"><button class="primary wide" id="capture" disabled>Lưu ảnh QSXGA</button><a id="last" hidden target="_blank"><button>Mở ảnh</button></a></div></section><aside class="card"><div class="head"><b>Thiết bị</b><span id="up" class="muted">—</span></div><div class="stats"><div class="stat"><span class="muted">microSD</span><b id="sd">—</b></div><div class="stat"><span class="muted">Ảnh lưu</span><b id="count">—</b></div><div class="stat"><span class="muted">Wi‑Fi</span><b id="wifi">—</b></div><div class="stat"><span class="muted">Tệp dở</span><b id="tmp">—</b></div></div><p class="note" id="notice"></p></aside></div><details class="card" open><summary>Điều chỉnh camera</summary><div class="profiles"><button data-profile="auto">Auto</button><button data-profile="bright">Xưởng tối</button><button data-profile="neutral">Trung tính</button></div><div id="sliders"></div><div class="toggles"><label><input type="checkbox" data-setting="awb"> Auto cân bằng trắng</label><label><input type="checkbox" data-setting="exposure"> Auto phơi sáng</label><label><input type="checkbox" data-setting="gain"> Auto gain</label></div><div class="actions"><span class="note" id="settingsnote">Đã áp dụng — chưa lưu sau reboot.</span><button class="primary" id="savesettings">Lưu cấu hình này</button></div></details><section class="card"><div class="head"><div><b>Ảnh trên thẻ</b><div class="note" id="gallerynote">Đang tải…</div></div><button id="refresh">Tải lại</button></div><div class="gallery" id="gallery"></div></section><details class="card"><summary>Thiết lập Wi‑Fi nhà</summary><form id="wf" class="actions"><input name="ssid" placeholder="Tên Wi‑Fi" required><input name="password" type="password" placeholder="Mật khẩu" required><button class="primary">Lưu và kết nối</button></form><p class="note" id="wifinote"></p></details></main><dialog id="viewer"><img id="full" alt="Ảnh đã lưu"><button onclick="viewer.close()">Đóng</button></dialog><script>const $=s=>document.querySelector(s),cam=$('#cam'),notice=$('#notice'),sliders=[['brightness','Độ sáng',-2,2],['contrast','Tương phản',-2,2],['saturation','Màu',-2,2],['sharpness','Độ nét',-2,2],['quality','JPEG quality',8,20]];let t;function next(){cam.src='/snapshot.jpg?t='+Date.now()}cam.onload=()=>t=setTimeout(next,350);cam.onerror=()=>t=setTimeout(next,1200);function up(s){$('#up').textContent='Uptime '+Math.floor(s.uptime_s/60)+'m';$('#sd').textContent=s.sd_ready?'Sẵn sàng':'Chưa sẵn sàng';$('#count').textContent=s.images+' ảnh';$('#wifi').textContent=s.wifi==='connected'?s.ssid:s.wifi;$('#tmp').textContent=s.tmp_cleaned;$('#capture').disabled=!s.sd_ready;$('#online').textContent='● Online'}async function status(){try{up(await fetch('/api/status',{cache:'no-store'}).then(r=>r.json()))}catch(e){$('#online').textContent='● Mất kết nối'}}async function api(url,data){let r=await fetch(url,{method:'POST',body:new URLSearchParams(data)});if(!r.ok)throw Error(await r.text());return r.headers.get('content-type').includes('json')?r.json():r.text()}function setUI(s){sliders.forEach(([n,,a,b])=>{let x=$('[data-setting="'+n+'"]');x.min=a;x.max=b;x.value=s[n];x.nextElementSibling.textContent=s[n]});['awb','exposure','gain'].forEach(n=>$('[data-setting="'+n+'"]').checked=s[n])}async function settings(){let s=await fetch('/api/camera-settings').then(r=>r.json());setUI(s)}sliders.forEach(([n,label,min,max])=>{$('#sliders').insertAdjacentHTML('beforeend',`<div class="row"><label>${label}</label><input data-setting="${n}" type="range" min="${min}" max="${max}"><output>—</output></div>`)});document.addEventListener('change',async e=>{let n=e.target.dataset.setting;if(!n)return;try{let s=await api('/api/camera-settings',{name:n,value:e.target.type==='checkbox'?(e.target.checked?1:0):e.target.value});setUI(s);$('#settingsnote').textContent='Đã áp dụng — chưa lưu sau reboot.'}catch(x){$('#settingsnote').textContent='Lỗi: '+x.message}});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=async()=>{try{setUI(await api('/api/camera-profile',{profile:b.dataset.profile}));$('#settingsnote').textContent='Profile đã áp dụng — chưa lưu.'}catch(e){$('#settingsnote').textContent='Lỗi: '+e.message}});$('#savesettings').onclick=async()=>{try{$('#settingsnote').textContent=await api('/api/camera-settings/save',{})}catch(e){$('#settingsnote').textContent='Lỗi: '+e.message}};async function loadGallery(){try{let d=await fetch('/api/gallery').then(r=>r.json());$('#gallerynote').textContent=d.total+' ảnh · 24 ảnh mới nhất';let g=$('#gallery');g.innerHTML=d.images.length?'':'<div class="empty">Chưa có ảnh.</div>';d.images.forEach(n=>{let b=document.createElement('button');b.className='thumb';b.innerHTML=`<img loading="lazy" src="/image/${n}" alt="${n}"><span>${n}</span>`;b.onclick=()=>{full.src='/image/'+n;viewer.showModal()};g.append(b)})}catch(e){$('#gallery').innerHTML='<div class="empty">Không tải được thư viện ảnh.</div>'}}$('#capture').onclick=async()=>{try{notice.textContent='Đang lưu…';let p=await api('/api/capture',{});notice.textContent='Đã lưu: '+p;last.href='/image/'+p.split('/').pop();last.hidden=false;loadGallery()}catch(e){notice.textContent='Lỗi: '+e.message}finally{status()}};$('#refresh').onclick=loadGallery;$('#wf').onsubmit=async e=>{e.preventDefault();try{$('#wifinote').textContent=await api('/api/wifi',new FormData(e.target))}catch(x){$('#wifinote').textContent='Lỗi: '+x.message}};setInterval(status,3000);status();settings();loadGallery();next();</script>)HTML";
